import AppKit
import ScreenCaptureKit
import CoreMedia

final class Delegate: NSObject, SCStreamOutput, SCStreamDelegate {
  var frameCount = 0
  func stream(_ stream: SCStream, didOutputSampleBuffer sampleBuffer: CMSampleBuffer, of type: SCStreamOutputType) {
    guard type == .screen, CMSampleBufferIsValid(sampleBuffer) else { return }
    frameCount += 1
    if frameCount == 1 {
      print("FRAME_RECEIVED")
      fflush(stdout)
    }
  }
  func stream(_ stream: SCStream, didStopWithError error: Error) {
    print("STREAM_STOPPED_ERROR: \(error)")
    fflush(stdout)
  }
}

let window = NSWindow(
  contentRect: NSRect(x: 100, y: 100, width: 300, height: 200),
  styleMask: [.titled], backing: .buffered, defer: false)
window.title = "SCStreamCheck"
window.makeKeyAndOrderFront(nil)

let delegate = Delegate()

Task {
  do {
    print("REQUESTING_CURRENT_PROCESS_CONTENT")
    fflush(stdout)
    let content = try await SCShareableContent.currentProcess
    guard let scWindow = content.windows.first(where: { $0.title == "SCStreamCheck" }) ?? content.windows.first
    else {
      print("NO_OWN_WINDOW_FOUND")
      exit(1)
    }
    let filter = SCContentFilter(desktopIndependentWindow: scWindow)
    let config = SCStreamConfiguration()
    config.width = 300
    config.height = 200
    config.minimumFrameInterval = CMTime(value: 1, timescale: 10)
    config.showsCursor = false
    let stream = SCStream(filter: filter, configuration: config, delegate: delegate)
    try stream.addStreamOutput(delegate, type: .screen, sampleHandlerQueue: DispatchQueue(label: "sc.output"))
    print("STARTING_CAPTURE")
    fflush(stdout)
    try await stream.startCapture()
    print("STREAM_STARTED_OK")
    fflush(stdout)
    try await Task.sleep(nanoseconds: 3_000_000_000)
    print("FRAMES_RECEIVED_TOTAL: \(delegate.frameCount)")
    fflush(stdout)
    try await stream.stopCapture()
    exit(delegate.frameCount > 0 ? 0 : 2)
  } catch {
    print("ERROR: \(error)")
    fflush(stdout)
