import AppKit
import GhosttyKit

// THROWAWAY SPIKE — Stage 0 of the hover-preview plan (~/.claude/plans/ethereal-inventing-wolf.md).
// Not part of the feature. Delete before committing anything. ^⌥⌘P while a terminal pane is focused
// shows a small floating panel with a *live*, scaled (not resized) copy of that pane's real surface,
// via an ancestor CALayer.sublayerTransform — testing whether this composites correctly against
// libghostty's internally-installed CAMetalLayer, and whether it triggers a resize (it must not).

#if DEBUG
@MainActor
enum HoverPreviewSpike {
  private static var monitor: Any?
  private static var panel: NSPanel?
  private static var restoreInfo: (view: GhosttySurfaceView, superview: NSView, frame: NSRect)?

  static func install() {
    guard monitor == nil else { return }
    monitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
      let flags = event.modifierFlags.intersection([.command, .option, .control, .shift])
      guard flags == [.control, .option, .command],
        event.charactersIgnoringModifiers?.lowercased() == "p"
      else { return event }
      toggle()
      return nil
    }
    print("[HoverPreviewSpike] installed — ^⌥⌘P to toggle scaled live preview of the focused pane")
  }

  private static func toggle() {
    if panel != nil {
      restore()
      return
    }
    guard let window = NSApp.keyWindow else {
      print("[HoverPreviewSpike] no key window")
      return
    }
    guard let surfaceView = window.firstResponder as? GhosttySurfaceView else {
      print("[HoverPreviewSpike] focused responder is not a GhosttySurfaceView — click into a terminal pane first")
      NSSound.beep()
      return
    }
    show(surfaceView, ownerWindow: window)
  }

  private static func show(_ surfaceView: GhosttySurfaceView, ownerWindow: NSWindow) {
    guard let originalSuperview = surfaceView.superview else { return }
    let originalFrame = surfaceView.frame
    restoreInfo = (surfaceView, originalSuperview, originalFrame)

    let hostSize = CGSize(width: 260, height: 160)
    let scale = min(hostSize.width / originalFrame.width, hostSize.height / originalFrame.height)

    let host = NSView(frame: NSRect(origin: .zero, size: hostSize))
    host.wantsLayer = true
    host.layer?.masksToBounds = true
    host.layer?.backgroundColor = NSColor.black.cgColor

    // Reposition ONLY the origin (never the size) so the surface's own center lands at the host's
    // center, pre-transform. Setting .frame.size is what the critical finding says triggers a resize
    // (viewDidMoveToWindow -> updateMetalLayerSize -> ghostty_surface_set_size) — origin is safe.
    let originX = hostSize.width / 2 - originalFrame.width / 2
    let originY = hostSize.height / 2 - originalFrame.height / 2
    surfaceView.frame = NSRect(x: originX, y: originY, width: originalFrame.width, height: originalFrame.height)
    surfaceView.autoresizingMask = []
    host.addSubview(surfaceView)
    host.layer?.sublayerTransform = CATransform3DMakeScale(scale, scale, 1)

    let panel = NSPanel(
      contentRect: NSRect(origin: .zero, size: hostSize),
      styleMask: [.titled, .nonactivatingPanel, .utilityWindow],
      backing: .buffered, defer: false)
    panel.title = "HoverPreviewSpike (^⌥⌘P to close)"
    panel.contentView = host
    panel.level = .floating
    panel.isReleasedWhenClosed = false
    let ownerFrame = ownerWindow.frame
    panel.setFrameOrigin(NSPoint(x: ownerFrame.maxX + 20, y: ownerFrame.maxY - hostSize.height - 40))
    panel.orderFrontRegardless()
    Self.panel = panel

    print("[HoverPreviewSpike] shown — scale=\(scale), originalFrame=\(originalFrame), hostSize=\(hostSize)")
  }

  private static func restore() {
    guard let (view, superview, frame) = restoreInfo else {
      panel?.orderOut(nil)
      panel = nil
      return
    }
    view.frame = frame
    view.autoresizingMask = [.width, .height]
    superview.addSubview(view)
    panel?.orderOut(nil)
    panel = nil
    restoreInfo = nil
    print("[HoverPreviewSpike] restored to original superview/frame")
  }
}
#endif

