    let focused = s.addTab(for: targetA)
    let background = s.addTab(for: targetA)
    s.focus(focused.id, for: targetA)

    s.beginPreview(background.id, session: 1, for: targetA)  // session 1 starts
    s.beginPreview(background.id, session: 2, for: targetA)  // session 2 supersedes it (re-hover fast)

