    let tab2WronglyRetitled = app.descendants(matching: .any)
      .matching(NSPredicate(format: "identifier BEGINSWITH %@", "terminal.tab.echo after_hover"))
      .element(boundBy: 1)
    XCTAssertFalse(
      tab2WronglyRetitled.exists,
      "only one tab should show the after-hover command's title — a second match means it landed in " +
        "the hovered tab instead of the focused one")
