import XCTest

/// Regression coverage for the hover-preview feature (plan: ~/.claude/plans/ethereal-inventing-wolf.md)
/// stealing keyboard focus from the real active tab — found via real-mouse QA, not by any automated
/// test: hovering a backgrounded tab's chip silently made it the first responder (a stale
/// `GhosttySurfaceView.wantsFocus` left over from when it was last actually active triggered
/// `viewDidMoveToWindow`'s auto-claim once the hover-preview re-homed it into a real window).
///
/// The surface itself is Metal-rendered and exposes nothing queryable for "who currently holds first
/// responder" (the same CMT-3 gap `GhosttyActionDispatchUITests` documents), so this proves the
/// regression the way a real user would notice it: type into the real active tab, hover a DIFFERENT
/// tab's chip, then type again and confirm the keystrokes still land in the ORIGINALLY-FOCUSED tab's
/// chip POSITION — exercised through the shell's own OSC 0/2 retitling (issue #2), the same detector
/// `GhosttyActionDispatchUITests.testRunningCommandRetitlesTheTabChip` already uses. Checked by strip
/// POSITION, not by re-querying for the expected title prefix — a title-prefix query would still find
/// A match even if the WRONG chip (the hovered one) is the one that actually retitled, which would
/// silently pass right through the regression this test exists to catch.
///
/// Run with `make app-uitest` on a real GUI login session (XCUITest can't drive a headless run).
final class TerminalHoverPreviewUITests: XCTestCase {
  override func setUp() {
    super.setUp()
    continueAfterFailure = false
  }

  private func launchedApp() -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-WorkroomUITestNoRunCommand", "1"]
    app.launchArguments += ["-WorkroomUITestTerminalTabs", "2"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    return app
  }

  /// `.staticTexts` specifically, not `.descendants(matching: .any)` — the chip's title AND its close
  /// button share the same `terminal.tab.<title>` identifier prefix (`TabStripOverflowUITests`' own
  /// comment: "match only the title StaticText to count chips 1:1"), so an `.any` query returns more
  /// than one element per chip and breaks positional indexing.
  private func chipQuery(_ app: XCUIApplication) -> XCUIElementQuery {
    app.staticTexts.matching(NSPredicate(format: "identifier BEGINSWITH %@", "terminal.tab."))
  }

  /// The chip currently at strip position `index` — re-queried fresh each call (not a held
  /// reference), since a retitle changes the element's identifier/label but never its strip position.
  private func chip(_ app: XCUIApplication, at index: Int) -> XCUIElement {
    chipQuery(app).element(boundBy: index)
  }

  private func focusFirstTab(_ app: XCUIApplication) {
    app.activate()
    let query = chipQuery(app)
    XCTAssertTrue(query.firstMatch.waitForExistence(timeout: 20))
    XCTAssertGreaterThanOrEqual(query.count, 2, "the fixture must seed 2 terminal tabs")
    chip(app, at: 0).click()
    // The click lands before the surface is first responder; without a beat the first keystrokes are
    // dropped (same note as GhosttyActionDispatchUITests.focusTerminal).
    RunLoop.current.run(until: Date().addingTimeInterval(1))
  }

  private func run(_ app: XCUIApplication, _ line: String) {
    app.typeText(line + "\r")
  }

  /// Waits until the chip at strip position `index` retitles to contain `substring`.
  private func waitForChipLabel(
    _ app: XCUIApplication, at index: Int, toContain substring: String, timeout: TimeInterval = 20
  ) -> Bool {
    let deadline = Date().addingTimeInterval(timeout)
    while Date() < deadline {
      if chip(app, at: index).label.contains(substring) { return true }
      RunLoop.current.run(until: Date().addingTimeInterval(0.25))
    }
    return false
  }

  /// The regression test: hovering tab 2 while tab 1 is focused must not move keyboard focus.
  func testHoveringABackgroundTabDoesNotStealFocusFromTheActiveTab() {
    let app = launchedApp()
    focusFirstTab(app)

    // Confirm keystrokes land in POSITION 0 before hovering, establishing the baseline. `sleep 3`
    // first keeps the whole line as the tab's title long enough to reliably poll — a bare `echo`
    // completes in milliseconds and its title can revert before a poll ever observes it (the same
    // reason `GhosttyActionDispatchUITests.testRunningCommandRetitlesTheTabChip` uses `sleep 6`, not
    // an instant command).
    run(app, "sleep 3; echo before_hover_marker")
    XCTAssertTrue(
      waitForChipLabel(app, at: 0, toContain: "before_hover"),
      "position 0 must retitle from its own running command")

    // Hover tab 2's chip (position 1) long enough to pass the hover-preview's dwell (0.4s) and
    // settle (0.05s).
    chip(app, at: 1).hover()
    RunLoop.current.run(until: Date().addingTimeInterval(1.0))

    // Type again — if hovering had stolen first responder, this would land at position 1 instead.
    run(app, "sleep 3; echo after_hover_marker")
    XCTAssertTrue(
      waitForChipLabel(app, at: 0, toContain: "after_hover"),
      "position 0 must still be the one receiving keystrokes after hovering position 1's chip — if "
        + "this fails, hovering silently stole first responder (the regression this test exists for)"
    )
    XCTAssertFalse(
      chip(app, at: 1).label.contains("after_hover"),
      "position 1 (the hovered chip) must not have received the command instead")
  }

  /// Hovering the already-focused/visible tab is v1's explicit no-preview case — confirms it's also a
  /// safe no-op for focus, not just for the preview UI.
  func testHoveringTheAlreadyVisibleTabIsANoOp() {
    let app = launchedApp()
    focusFirstTab(app)

    chip(app, at: 0).hover()  // tab 1 is already focused/visible — v1 shows no preview for it
    RunLoop.current.run(until: Date().addingTimeInterval(1.0))

    run(app, "sleep 3; echo still_focused_marker")
    XCTAssertTrue(
      waitForChipLabel(app, at: 0, toContain: "still_focused"),
      "hovering the already-active tab's own chip must not disturb focus")
  }
}

import AppKit
import QuartzCore
import XCTest

@testable import Workroom

/// Coverage for the actual production `PreviewFrameSource` (Candidate A) — none of
/// `TerminalHoverPreviewControllerTests` exercise this, since they all inject a `FakeFrameSource` to
/// keep the state-machine tests fast/isolated. This file exists specifically because that split let a
/// real bug through: found via a real-mouse QA pass ("hover selected the tab, detail pane went empty"),
/// not caught by any automated test until this one.
@MainActor
final class TransformScaleFrameSourceTests: XCTestCase {
  private var window: NSWindow!

  override func setUpWithError() throws {
    try super.setUpWithError()
    try XCTSkipUnless(GhosttyApp.shared.app != nil, "requires the libghostty runtime")
    window = NSWindow(
      contentRect: NSRect(x: 0, y: 0, width: 800, height: 480),
      styleMask: [.titled], backing: .buffered, defer: true)
  }

  /// The regression: `TerminalContainerView.mount(in:)` only ever writes `wantsFocus` on whichever
  /// surface is CURRENTLY its `view:` — a backgrounded tab's surface keeps whatever stale value it had
  /// from when it was last actually active (typically `true`, from being the newly-focused tab at
  /// creation; nothing resets it when a solo tab is swapped away entirely). Mounting that surface into
  /// the preview host must not let a stale `true` steal first responder from whatever the real active
  /// view is via `viewDidMoveToWindow`'s `if wantsFocus, window.firstResponder !== self {
  /// window.makeFirstResponder(self) }`.
  func testMountNeverStealsFirstResponderFromCurrentlyFocusedView() {
    // The "hovered" surface — mounted once (as if it had been the active tab), leaving a stale
    // `wantsFocus == true`, matching what `TerminalContainerView.mount(in:)` would have set.
    let surface = GhosttySurfaceView(
      workingDirectory: NSTemporaryDirectory(), command: nil, spawnsSurface: true)
    surface.frame = window.contentView!.bounds
    window.contentView!.addSubview(surface)
    surface.wantsFocus = true
    defer { surface.tearDown() }

    // A different view stands in for the real, currently-active tab's surface.
    let activeView = NSView()
    window.contentView!.addSubview(activeView)
    XCTAssertTrue(window.makeFirstResponder(activeView))

    // Background the hovered surface (as `TerminalContainerView`'s detach-on-switch-away does), then
    // mount it into a preview host that's part of the same real window.
    surface.removeFromSuperview()
    let host = NSView(frame: NSRect(x: 0, y: 0, width: 260, height: 160))
    host.wantsLayer = true
    window.contentView!.addSubview(host)

    let source = TransformScaleFrameSource(scheduling: DispatchQueueScheduling())
    XCTAssertTrue(source.mount(surface: surface, host: host))

    XCTAssertFalse(
      surface.wantsFocus, "mount must clear a stale wantsFocus so it can never auto-claim focus")
    XCTAssertTrue(
      window.firstResponder === activeView,
      "mounting a hover preview must never steal first responder from the real active view")
  }

  func testMountScalesToFitAndNeverResizesTheSurface() {
    let surface = GhosttySurfaceView(
      workingDirectory: NSTemporaryDirectory(), command: nil, spawnsSurface: true)
    surface.frame = NSRect(x: 0, y: 0, width: 800, height: 480)
    window.contentView!.addSubview(surface)
    defer { surface.tearDown() }
    let originalSize = surface.frame.size

    surface.removeFromSuperview()
    let host = NSView(frame: NSRect(x: 0, y: 0, width: 260, height: 160))
    host.wantsLayer = true
    window.contentView!.addSubview(host)

    let source = TransformScaleFrameSource(scheduling: DispatchQueueScheduling())
    XCTAssertTrue(source.mount(surface: surface, host: host))

    XCTAssertEqual(
      surface.frame.size, originalSize,
      "the critical finding's rule: mount must never write .frame.size — only .frame.origin")
    let transform = host.layer?.sublayerTransform ?? CATransform3DIdentity
    XCTAssertFalse(
      CATransform3DIsIdentity(transform),
      "the visual shrink must come from a compositing transform, not a geometry change")
  }
}

import AppKit
import XCTest

@testable import Workroom

// MARK: - Fakes (the injected Scheduling/FrameSource seam, Tension 2)

private final class FakeCancellable: PreviewCancellable {
  private(set) var cancelled = false
  func cancel() { cancelled = true }
}

/// Captures every scheduled block instead of running it — tests fire them explicitly, so the dwell
/// and settle delays never actually need to elapse.
private final class FakeScheduling: PreviewScheduling {
  private(set) var entries: [(cancellable: FakeCancellable, block: () -> Void)] = []

  func schedule(after delay: TimeInterval, _ block: @escaping () -> Void) -> PreviewCancellable {
    let cancellable = FakeCancellable()
    entries.append((cancellable, block))
    return cancellable
  }

  /// Fires the most recently scheduled block, if it hasn't been cancelled.
  func fireLast() {
    guard let entry = entries.last, !entry.cancellable.cancelled else { return }
    entry.block()
  }
}

private final class FakeFrameSource: PreviewFrameSource {
  var mountResult = true
  private(set) var mountCalled = false
  private(set) var unmountCalled = false
  private(set) var stopPresentingCalled = false
  private var onFirstFrame: (() -> Void)?

  func mount(surface: GhosttySurfaceView, host: NSView) -> Bool {
    mountCalled = true
    return mountResult
  }

  func startPresenting(onFirstFrame: @escaping () -> Void) {
    self.onFirstFrame = onFirstFrame
  }

  /// Fires the `onFirstFrame` callback passed to `startPresenting`, if any.
  func fireFirstFrame() {
    onFirstFrame?()
  }

  func stopPresenting() {
    stopPresentingCalled = true
  }

  func unmount() {
    unmountCalled = true
  }
}

@MainActor
final class TerminalHoverPreviewControllerTests: XCTestCase {
  private let target = TerminalTarget(
    id: "wr|/p|hover", title: "hover", path: "/tmp", isMissing: false)
  private var window: NSWindow!
  /// Every real surface created via `makeSessions()`'s factory, torn down in `tearDown()` — each one
  /// spawns a real shell (`spawnsSurface: true`, needed for `hasSurface`/`isPreviewEligible` to ever be
  /// true), so cleanup here matters the same way it does in production (no orphaned shells).
  private var createdSurfaces: [GhosttySurfaceView] = []

  override func setUpWithError() throws {
    try super.setUpWithError()
    try XCTSkipUnless(GhosttyApp.shared.app != nil, "requires the libghostty runtime")
    window = NSWindow(
      contentRect: NSRect(x: 0, y: 0, width: 800, height: 480),
      styleMask: [.titled], backing: .buffered, defer: true)
  }

  override func tearDown() {
    for surface in createdSurfaces { surface.tearDown() }
    createdSurfaces = []
    super.tearDown()
  }

  /// A `TerminalSessions` whose surfaces are pre-attached to a real (offscreen) window with a REAL
  /// spawned surface (`spawnsSurface: true`) — the controller's `armHover` gates on
  /// `isPreviewEligible`/`hasSurface`, which reflects a genuine `ghostty_surface_t`, not just a mounted
  /// `NSView`. Requires the libghostty runtime to be ready in the test host — skip-gated by the one
  /// caller that constructs sessions this way, matching `TerminalFocusAdoptionLiveSurfaceTests`'
  /// precedent (a skipped test beats a flaky one).
  ///
  /// Also mimics `TerminalContainerView`'s real mount/detach behavior via `onFocusChange`: production
  /// keeps only the currently-focused/visible tab's surface attached to a window — every OTHER tab's
  /// surface is detached (`superview == nil`). Earlier versions of this fixture attached every surface
  /// permanently, which is exactly the unrealistic setup that let a real bug through undetected: `mount()`
  /// used to `guard let superview = surface.superview else { return }`, silently no-oping for every
  /// genuinely-backgrounded tab (found via a real-mouse hover test showing nothing at all — no crash, no
  /// log — after this test suite had already gone green against the too-generous old fixture).
  private func makeSessions() -> TerminalSessions {
    let sessions = TerminalSessions()
    sessions.makeView = { [window, weak self] _, cwd, _ in
      let view = GhosttySurfaceView(workingDirectory: cwd, command: nil, spawnsSurface: true)
      view.frame = window!.contentView!.bounds
      window!.contentView!.addSubview(view)
      self?.createdSurfaces.append(view)
      return view
    }
    var previouslyFocused: TerminalTab.ID?
    sessions.onFocusChange = { [weak sessions, target] _, newFocusedID in
      if let previouslyFocused, previouslyFocused != newFocusedID {
        sessions?.tab(previouslyFocused, for: target)?.surface?.removeFromSuperview()
      }
      previouslyFocused = newFocusedID
    }
    return sessions
  }

  private func makeController(
    sessions: TerminalSessions, scheduling: FakeScheduling, frameSource: FakeFrameSource
  )
    -> TerminalHoverPreviewController
  {
    TerminalHoverPreviewController(
      sessions: sessions, scheduling: scheduling, dwell: 0.4, makeFrameSource: { frameSource })
  }

  // MARK: Gates

  func testArmHoverDoesNothingForAlreadyVisibleTab() {
    let sessions = makeSessions()
    let focused = sessions.addTab(for: target)  // focused == visible
    let scheduling = FakeScheduling()
    let controller = makeController(
      sessions: sessions, scheduling: scheduling, frameSource: FakeFrameSource())

    controller.armHover(tab: focused, target: target)

    XCTAssertEqual(controller.phase, .idle, "an already-visible tab must never arm")
    XCTAssertTrue(scheduling.entries.isEmpty, "no dwell timer should be scheduled")
  }

  func testArmHoverDoesNothingWithoutASurface() {
    let sessions = TerminalSessions()
    sessions.makeView = { _, cwd, _ in
      // Never attached to a window, so its surface stays nil.
      GhosttySurfaceView(workingDirectory: cwd, command: nil, spawnsSurface: false)
    }
    let focusedDummy = sessions.addTab(for: target)
    let background = sessions.addTab(for: target)
    sessions.focus(focusedDummy.id, for: target)
    let scheduling = FakeScheduling()
    let controller = makeController(
      sessions: sessions, scheduling: scheduling, frameSource: FakeFrameSource())

    controller.armHover(tab: background, target: target)

    XCTAssertEqual(controller.phase, .idle, "a tab with no live surface must never arm")
    XCTAssertTrue(scheduling.entries.isEmpty)
  }

  // MARK: Happy path

  func testFullHoverCycleMountsPresentsAndTearsDown() {
    let sessions = makeSessions()
    let focused = sessions.addTab(for: target)
    let background = sessions.addTab(for: target)
    sessions.focus(focused.id, for: target)
    let scheduling = FakeScheduling()
    let frameSource = FakeFrameSource()
    let controller = makeController(
      sessions: sessions, scheduling: scheduling, frameSource: frameSource)

    controller.armHover(tab: background, target: target)
    XCTAssertEqual(controller.phase, .armed(tabID: background.id))
    XCTAssertFalse(frameSource.mountCalled, "must not mount before the dwell elapses")

    scheduling.fireLast()  // dwell elapses → resolve → mount
    XCTAssertTrue(frameSource.mountCalled)
    XCTAssertEqual(
      background.surface?.isPaneVisibleForTesting, true,
      "beginPreview must have un-occluded the background tab")
    XCTAssertNotNil(controller.previewHost)

    // The settle callback from startPresenting (not scheduling-routed).
    frameSource.fireFirstFrame()
    XCTAssertEqual(controller.phase, .visible(tabID: background.id))

    controller.cancelHover()  // hover ends
    XCTAssertEqual(controller.phase, .idle)
    XCTAssertTrue(frameSource.stopPresentingCalled)
    XCTAssertTrue(frameSource.unmountCalled)
    XCTAssertNil(controller.previewHost)
    XCTAssertEqual(
      background.surface?.isPaneVisibleForTesting, false,
      "endPreview must have re-occluded the background tab on teardown")
  }

  // MARK: Cancellation / supersession

  func testCancelHoverDuringDwellNeverMounts() {
    let sessions = makeSessions()
    let focused = sessions.addTab(for: target)
    let background = sessions.addTab(for: target)
    sessions.focus(focused.id, for: target)
    let scheduling = FakeScheduling()
    let frameSource = FakeFrameSource()
    let controller = makeController(
      sessions: sessions, scheduling: scheduling, frameSource: frameSource)

    controller.armHover(tab: background, target: target)
    controller.cancelHover()  // mouse left before the dwell fired

    scheduling.fireLast()  // the (cancelled) dwell work, if it somehow ran anyway
    XCTAssertFalse(frameSource.mountCalled, "a cancelled dwell must never mount")
    XCTAssertEqual(controller.phase, .idle)
  }

  func testArmingANewHoverSupersedesTheStaleOne() {
    let sessions = makeSessions()
    let focused = sessions.addTab(for: target)
    let backgroundA = sessions.addTab(for: target)
    let backgroundB = sessions.addTab(for: target)
    sessions.focus(focused.id, for: target)
    let scheduling = FakeScheduling()
    let frameSource = FakeFrameSource()
    let controller = makeController(
      sessions: sessions, scheduling: scheduling, frameSource: frameSource)

    controller.armHover(tab: backgroundA, target: target)
    let staleGeneration = scheduling.entries.last!
    // B supersedes A before A's dwell fired.
    controller.armHover(tab: backgroundB, target: target)

    // A's stale dwell work fires anyway (simulates a race, not just a cancel).
    staleGeneration.block()
    XCTAssertFalse(
      frameSource.mountCalled, "A's superseded dwell must be a no-op even if it manages to fire")

    scheduling.fireLast()  // B's own dwell
    XCTAssertTrue(frameSource.mountCalled)
    XCTAssertEqual(
      controller.phase, .armed(tabID: backgroundB.id), "mount doesn't change phase yet")
    // The observable proxy for "B, not A, was mounted": beginPreview un-occludes exactly one tab.
    XCTAssertEqual(backgroundB.surface?.isPaneVisibleForTesting, true)
    XCTAssertEqual(backgroundA.surface?.isPaneVisibleForTesting, false)
  }

  // MARK: Failure routing (eng review Codex #3 — a stale/failed step must clean up, not just no-op)

  func testMountFailureRoutesToIdleWithoutLeavingStatePartiallySet() {
    let sessions = makeSessions()
    let focused = sessions.addTab(for: target)
    let background = sessions.addTab(for: target)
    sessions.focus(focused.id, for: target)
    let scheduling = FakeScheduling()
    let frameSource = FakeFrameSource()
    frameSource.mountResult = false
    let controller = makeController(
      sessions: sessions, scheduling: scheduling, frameSource: frameSource)

    controller.armHover(tab: background, target: target)
    scheduling.fireLast()

    XCTAssertEqual(controller.phase, .idle)
    XCTAssertNil(controller.previewHost)
    XCTAssertEqual(
      background.surface?.isPaneVisibleForTesting, false,
      "a failed mount must never have un-occluded the tab")
  }

  // MARK: Tab closed mid-hover

  func testTabClosedMidDwellNeverMounts() {
    let sessions = makeSessions()
    let focused = sessions.addTab(for: target)
    let background = sessions.addTab(for: target)
    sessions.focus(focused.id, for: target)
    let scheduling = FakeScheduling()
    let frameSource = FakeFrameSource()
    let controller = makeController(
      sessions: sessions, scheduling: scheduling, frameSource: frameSource)

    controller.armHover(tab: background, target: target)
    sessions.closeTab(background.id, for: target)

    scheduling.fireLast()
    XCTAssertFalse(frameSource.mountCalled, "a tab closed mid-dwell must never be mounted")
    XCTAssertEqual(controller.phase, .idle)
  }
}

import AppKit
import XCTest

@testable import Workroom

/// Guards the keyboard-input regression we hit during QA: macOS reports arrows / F-keys / nav keys
/// as function-key private-use scalars (U+F700–U+F8FF), which must NOT be forwarded as text (else
/// they insert a stray glyph), while DEL (U+007F, the Backspace key) MUST be kept and forwarded so
/// the shell receives the erase byte. See `GhosttySurfaceView.filterSpecialCharacters`.
final class TerminalKeyTextFilterTests: XCTestCase {
  private func filter(_ s: String) -> String { GhosttySurfaceView.filterSpecialCharacters(s) }

  func testEmptyStringStaysEmpty() {
    XCTAssertEqual(filter(""), "")
  }

  func testPlainTextPassesThrough() {
    XCTAssertEqual(filter("a"), "a")
    XCTAssertEqual(filter("é"), "é")
    XCTAssertEqual(filter("abc"), "abc")  // first scalar decides; whole string returned
  }

  func testFunctionKeyPrivateUseRangeIsDropped() {
    // The bug: these passed the old `>= 0x20` filter and got sent as text → "weird characters".
    XCTAssertEqual(filter("\u{F700}"), "", "up-arrow sentinel must be dropped")
    XCTAssertEqual(filter("\u{F701}"), "", "down-arrow sentinel must be dropped")
    XCTAssertEqual(filter("\u{F8FF}"), "", "end of the PUA function-key range must be dropped")
  }

  func testControlCharactersAreDropped() {
    XCTAssertEqual(filter("\u{0008}"), "", "BS (^H) is a control char")
    XCTAssertEqual(filter("\u{001B}"), "", "ESC is a control char")
    XCTAssertEqual(filter("\u{000D}"), "", "CR is a control char")
  }

  func testDelIsKept() {
    // The backspace fix: DEL (0x7F) must be forwarded as text (the pinned libghostty mis-encodes the
    // backspace *keycode*, so we send the byte instead).
    XCTAssertEqual(filter("\u{007F}"), "\u{007F}")
  }
}

/// Guards the overlay-scrollbar geometry (the indicator restored after the SwiftTerm → libghostty
/// migration). Pure math over libghostty's `total`/`offset`/`len` (rows). Bottom-left origin: the
/// live position sits at the bottom of the track. See `GhosttySurfaceView.scrollbarThumbRect`.
final class ScrollbarGeometryTests: XCTestCase {
  // 200pt track: bounds height 204 minus 2*inset(2).
  private let bounds = CGRect(x: 0, y: 0, width: 100, height: 204)
  private let width: CGFloat = 7
  private let inset: CGFloat = 2
  private let minThumb: CGFloat = 28

  private func rect(total: UInt64, offset: UInt64, len: UInt64) -> CGRect? {
    GhosttySurfaceView.scrollbarThumbRect(
      total: total, offset: offset, len: len, bounds: bounds,
      width: width, inset: inset, minThumb: minThumb)
  }

  func testHiddenWhenNothingToScroll() {
    XCTAssertNil(rect(total: 200, offset: 0, len: 200), "viewport == buffer → no thumb")
    XCTAssertNil(rect(total: 100, offset: 0, len: 200), "len > total (degenerate) → no thumb")
  }

  func testThumbSizeIsProportional() throws {
    // total 400, len 200 → half the 200pt track = 100pt thumb.
    let r = try XCTUnwrap(rect(total: 400, offset: 200, len: 200))
    XCTAssertEqual(r.height, 100, accuracy: 0.001)
    XCTAssertEqual(r.width, width)
    XCTAssertEqual(r.origin.x, bounds.width - width - inset, accuracy: 0.001)  // right edge
  }

  func testLivePositionSitsAtBottom() throws {
    // offset == total - len == live: thumb at the bottom (y == inset).
    let r = try XCTUnwrap(rect(total: 400, offset: 200, len: 200))
    XCTAssertEqual(r.origin.y, inset, accuracy: 0.001)
  }

  func testScrolledToTopSitsAtTop() throws {
    // offset 0: thumb at the top (y == inset + (track - thumb)).
    let r = try XCTUnwrap(rect(total: 400, offset: 0, len: 200))
    XCTAssertEqual(r.origin.y, inset + (200 - 100), accuracy: 0.001)
  }

  func testThumbClampsToMinimumHeight() throws {
    // Huge scrollback: proportional height (200*200/10000 = 4) clamps up to minThumb.
    let r = try XCTUnwrap(rect(total: 10000, offset: 0, len: 200))
    XCTAssertEqual(r.height, minThumb, accuracy: 0.001)
  }

  func testShouldFlashOnlyWhenScrolledBack() {
    // Live (at bottom) → no flash; scrolled back → flash; nothing-to-scroll → no flash.
    XCTAssertFalse(GhosttySurfaceView.scrollbarShouldFlash(total: 400, offset: 200, len: 200))
    XCTAssertTrue(GhosttySurfaceView.scrollbarShouldFlash(total: 400, offset: 100, len: 200))
    XCTAssertTrue(GhosttySurfaceView.scrollbarShouldFlash(total: 400, offset: 0, len: 200))
    XCTAssertFalse(GhosttySurfaceView.scrollbarShouldFlash(total: 200, offset: 0, len: 200))
  }

  func testIsScrolledBackDrivesGoToBottomButton() {
    // The go-to-bottom button shows exactly while scrolled back from the live bottom (issue #42):
    // hidden at the live bottom and when there's nothing to scroll; shown anywhere above the bottom.
    XCTAssertFalse(GhosttySurfaceView.isScrolledBack(total: 400, offset: 200, len: 200))  // live
    XCTAssertTrue(GhosttySurfaceView.isScrolledBack(total: 400, offset: 199, len: 200))  // 1 row up
    XCTAssertTrue(GhosttySurfaceView.isScrolledBack(total: 400, offset: 0, len: 200))  // top
    // No scrollback (buffer == viewport) → nothing below, so the button stays hidden.
    XCTAssertFalse(GhosttySurfaceView.isScrolledBack(total: 200, offset: 0, len: 200))
  }
}

/// Guards the focus re-sync that fixes "arrows/letters do nothing when a TUI prompt appears in a
/// pane that looks focused." Root cause: a zero-bounds attach defers `createSurface`, so
/// `becomeFirstResponder` runs while `surface == nil` and its `setSurfaceFocused(true)` no-ops — the
/// surface is later created blurred while the view holds first responder, and keys are dropped. The
/// fix re-syncs the focus flag at the end of `createSurface`. These exercise the decision
/// (`holdsFirstResponder`) and the action (`adoptFocusIfFirstResponder`) against a real `NSWindow`
/// with no live surface, mirroring how `canSpawnSurface` is unit-tested.
@MainActor
final class TerminalFocusAdoptionTests: XCTestCase {
  private func windowedView() -> (NSWindow, GhosttySurfaceView) {
    let window = NSWindow(
      contentRect: NSRect(x: 0, y: 0, width: 400, height: 300),
      styleMask: [.titled], backing: .buffered, defer: true)
    let view = GhosttySurfaceView(
      workingDirectory: NSTemporaryDirectory(), command: nil, spawnsSurface: false)
    view.frame = window.contentView!.bounds
    window.contentView!.addSubview(view)
    return (window, view)
  }

  func testHoldsFirstResponderReflectsWindowState() {
    let (window, view) = windowedView()
    XCTAssertTrue(window.makeFirstResponder(view), "the surface view must accept first responder")
    XCTAssertTrue(view.holdsFirstResponder)
    XCTAssertTrue(window.makeFirstResponder(nil))
    XCTAssertFalse(view.holdsFirstResponder)
  }

  func testAdoptFocusOnlyActsWhenFirstResponder() {
    let (window, view) = windowedView()
    _ = window.makeFirstResponder(nil)
    view.adoptFocusIfFirstResponder()
    XCTAssertEqual(view.focusSyncCount, 0, "must not adopt focus when not first responder")
    _ = window.makeFirstResponder(view)
    view.adoptFocusIfFirstResponder()
    XCTAssertEqual(view.focusSyncCount, 1, "adopts focus exactly once when first responder")
  }
}

/// The end-to-end ordering repro, gated on the libghostty runtime being available in the test host
/// (`XCTSkipUnless`) — a skipped test beats a flaky one. Reproduces: the view becomes first responder
/// while the surface is still nil (zero-bounds attach), then the surface is created on resize; the
/// fix must re-sync focus so `focusSyncCount` bumps during `createSurface`.
@MainActor
final class TerminalFocusAdoptionLiveSurfaceTests: XCTestCase {
  func testSurfaceCreatedAfterFirstResponderAdoptsFocus() throws {
    try XCTSkipUnless(GhosttyApp.shared.app != nil, "requires the libghostty runtime")
    let window = NSWindow(
      contentRect: NSRect(x: 0, y: 0, width: 400, height: 300),
      styleMask: [.titled], backing: .buffered, defer: true)
    let view = GhosttySurfaceView(
      workingDirectory: NSTemporaryDirectory(), command: nil, spawnsSurface: true)
    defer { view.tearDown() }
    view.frame = .zero  // zero bounds → createSurface defers on attach
    window.contentView!.addSubview(view)
    XCTAssertTrue(window.makeFirstResponder(view))
    XCTAssertEqual(view.focusSyncCount, 0, "no surface yet — nothing to sync")
    view.setFrameSize(NSSize(width: 400, height: 300))  // deferred createSurface runs now
    XCTAssertEqual(
      view.focusSyncCount, 1, "createSurface must re-sync focus for the first-responder view")
  }
}

/// `hasSurface` and `isPaneVisibleForTesting` — the two testing seams the hover-preview feature added
/// (`GhosttySurfaceView.swift`).
@MainActor
final class GhosttySurfaceViewHoverPreviewSeamTests: XCTestCase {
  func testHasSurfaceReflectsCreationAndTearDown() {
    let window = NSWindow(
      contentRect: NSRect(x: 0, y: 0, width: 400, height: 300),
      styleMask: [.titled], backing: .buffered, defer: true)
    let view = GhosttySurfaceView(
      workingDirectory: NSTemporaryDirectory(), command: nil, spawnsSurface: true)
    XCTAssertFalse(view.hasSurface, "not attached to a window yet — no surface")

    view.frame = window.contentView!.bounds
    window.contentView!.addSubview(view)
    XCTAssertTrue(view.hasSurface, "attaching to a window creates the surface")

    view.tearDown()
    XCTAssertFalse(view.hasSurface, "tearDown must clear the surface")
  }

  func testIsPaneVisibleForTestingReflectsSetVisible() {
    let view = GhosttySurfaceView(
      workingDirectory: NSTemporaryDirectory(), command: nil, spawnsSurface: false)
    XCTAssertTrue(view.isPaneVisibleForTesting, "a fresh view defaults to visible")
    view.setVisible(false)
    XCTAssertFalse(view.isPaneVisibleForTesting)
    view.setVisible(true)
    XCTAssertTrue(view.isPaneVisibleForTesting)
  }
}

