  // Only unmount/restore if the surface is STILL parented in OUR preview host — a real focus/tab
  // switch may have already re-homed it elsewhere (`TerminalContainerView.mount(in:)`) since this
  // session mounted it. Forcing it back to `originalSuperview`, or letting `unmount()` rip it out,
  // would blank a tab the user just switched to (found via real-mouse QA: clicking the previewed
  // tab re-homed its surface into the real container, then this teardown's unconditional
  // `removeFromSuperview()`/restore yanked it straight back out).
  if let surface = mountedSurface, surface.superview === mountedHost {
    activeFrameSource?.unmount()
    if let superview = originalSuperview, let frame = originalFrame {
      surface.frame = frame
      surface.autoresizingMask = [.width, .height]
      superview.addSubview(surface)
    }
  }

  activeFrameSource = nil
  if let target = activeTarget, let tabID = activeTabID, let session = activeSession {
    sessions.endPreview(tabID, session: session, for: target)
  }
  mountedSurface = nil
  mountedHost = nil
  originalSuperview = nil
  originalFrame = nil
  previewHost = nil
  activeTarget = nil
  activeTabID = nil
  activeSession = nil
}

